head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf30600";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — result

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_result", fn: function(){ return (!(String(((dma_pageContext.get("result") ?? "")) == null ? '' : ((dma_pageContext.get("result") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_searchWord", fn: function () { return String((dma_pageContext.get("searchWord") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const pageIndex = "" + dma_page.get("currentPage") + "";
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf30600.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(bizform vs bizformdownload) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":5
        ,"mmenu":7
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf30600' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf30600.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_searchWord_onkeyup
 * @description ipt_searchWord 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_searchWord_onkeyup = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        if(event.keyCode === 13) { await scwin.goSearch(); };fn_boardCheck(selfVar)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf30600.ipt_searchWord_onkeyup' }); }
};

/**
 * @method
 * @name btn_goSearch_onclick
 * @description btn_goSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goSearch_onclick = async function(e){
    try {
        await scwin.goSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf30600.btn_goSearch_onclick' }); }
};

/**
 * @method
 * @name grd_result_oncellclick
 * @description grd_result 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: downloadFile (조건 미해석) */
        if (columnId === "__rowAct") { await scwin.goView(r["contnId"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_goSearch
 * @description go Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goSearch = async function () {
    const sbmOptions = {
        id: "tx_goSearch",
        method: "post",
        action: "/info/bizform.do?method=bizformList",
        ref: "dma_goSearchReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_goSearch2
 * @description go Search2 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goSearch2 = async function () {
    const sbmOptions = {
        id: "tx_goSearch2",
        method: "post",
        action: "/info/bizform.do?method=bizformList",
        ref: "dma_goSearch2Req",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_goView
 * @description go View 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goView = async function () {
    const sbmOptions = {
        id: "tx_goView",
        method: "post",
        action: "/info/bizform.do?method=bizformView",
        ref: "dma_goViewReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_downloadFile
 * @description download File 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_downloadFile = async function () {
    try { return await $c.data.downFile("/info/bizformDownload.do", "", ($c.util.getComponent("dma_downloadFileReq") ? $c.util.getComponent("dma_downloadFileReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_result_fmt_column2
 * @description grd result fmt column2 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_fmt_column2 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "fileCount") ?? '') : '');
        if (Number(v) > 0) { return (console.error('[sdd] 미실현 라벨 갈래: column2 (image)'), String(data ?? '')); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_result.column2" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_result_fmt_attachFileNm
 * @description grd result fmt attach File Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_fmt_attachFileNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "attachFileNo") ?? '') : '');
        if (v !== '') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: attachFileNm (image)'), String(data ?? '')) + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_result.attachFileNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_result_fillAct
 * @description grd result fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.fillAct' });
    }
};

/**
 * @method
 * @name goSearch
 * @description go Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSearch = async function () {
    const fm = (document.JLDINF30600 || { elements: [] });
    $c.util.getComponent('ipt_pageIndex').setValue("1");
    fm.action = "/info/bizform.do?method=bizformList";
    blockLoading();
    await scwin.tx_goSearch();
};

/**
 * @method
 * @name goSearch2
 * @description go Search2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSearch2 = async function () {
    const fm = (document.JLDINF30600 || { elements: [] });
    fm.action = "/info/bizform.do?method=bizformList";
    blockLoading();
    await scwin.tx_goSearch2();
};

/**
 * @method
 * @name goView
 * @description go View 처리
 * @param {*} id id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goView = async function (id) {
    const frm = (document.JLDINF30600 || { elements: [] });
    $c.util.getComponent('dma_goSearchReq').set('contnId', id);
    frm.action = "/info/bizform.do?method=bizformView";
    await scwin.tx_goView();
};

/**
 * @method
 * @name downloadFile
 * @description download File 처리
 * @param {*} contn_id contn_id
 * @param {*} attach_file_no attach_file_no
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.downloadFile = async function (contn_id, attach_file_no) {
    const obj = (document.downloadForm || { elements: [] });
    obj.action = '/info/bizformDownload.do';
    $c.util.getComponent('dma_goSearchReq').set('method', 'bizformDownload');
    $c.util.getComponent("dma_goSearchReq").set("contnId", contn_id);
    $c.util.getComponent("dma_goSearchReq").set("attachFileNo", attach_file_no);
    await scwin.tx_downloadFile();
};

/**
 * @method
 * @name krxpage_pagenavigator_80_onclick
 * @description krxpage_pagenavigator_80 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_80_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_goSearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_80.page' }); } await scwin.goSearch2(); };
